export function Mark({ size }: { size?: number }) {
  return (
    <svg className={styles.mark} viewBox="0 0 100 100" aria-hidden="true" style={size ? { width: size, height: size } : undefined}>
      <path d={MARK_H} className={styles.ink} />
      <path d={MARK_Z} className={styles.red} />
    </svg>
  )
}

/** Monogram and wordmark side by side. size = monogram height in px (default 28). */
export default function Logo({ size = 28 }: { size?: number }) {
  return (
    <div className={styles.logo} style={{ '--mark-size': `${size}px` } as CSSProperties}>
      <Mark />
      <svg className={styles.word} viewBox={WORD_VIEWBOX} role="img" aria-label="StreamZH">
        <path d={WORD_STREAM} className={styles.ink} />
        <path d={WORD_ZH} className={styles.red} />
      </svg>
    </div>
  )
}
